import{_ as n,o as t,c as i,a5 as o}from"./chunks/framework.CsGesDJn.js";const u=JSON.parse('{"title":"Plan — G6 AI Features (Mobile)","description":"","frontmatter":{},"headers":[],"relativePath":"mobile/features/g6-ai-features/plan.md","filePath":"mobile/features/g6-ai-features/plan.md"}'),c={name:"mobile/features/g6-ai-features/plan.md"};function a(r,e,h,l,s,g){return t(),i("div",null,[...e[0]||(e[0]=[o('<h1 id="plan-—-g6-ai-features-mobile" tabindex="-1">Plan — G6 AI Features (Mobile) <a class="header-anchor" href="#plan-—-g6-ai-features-mobile" aria-label="Permalink to &quot;Plan — G6 AI Features (Mobile)&quot;">​</a></h1><p>&gt; <a href="./spec.html">spec.md</a> — chi tiết API/flows/business rules đầy đủ. File này là bản tóm tắt thứ tự implement + quyết định kỹ thuật chốt.</p><h2 id="thu-tu-implement-theo-dependency" tabindex="-1">Thứ tự implement (theo dependency) <a class="header-anchor" href="#thu-tu-implement-theo-dependency" aria-label="Permalink to &quot;Thứ tự implement (theo dependency)&quot;">​</a></h2><ol><li><strong>AI Hub</strong> — màn gốc, đơn giản, không phụ thuộc gì (3 card + credit balance).</li><li><strong>Generate Caption trước</strong> (đồng bộ, không cần polling, pattern đơn giản nhất) — làm mẫu cho 2 luồng còn lại.</li><li><strong>Generate Video</strong> (async, có polling + charge-upfront) — phức tạp hơn Caption do job lifecycle.</li><li><strong>Generate Image</strong> — <strong>chặn bởi chưa rõ credit flow thật và shape request/response</strong>, làm cuối cùng sau khi xác nhận với backend.</li><li><strong>Credit History</strong> — video history làm được ngay (<code>GET /videos</code> có sẵn); caption history <strong>chặn bởi thiếu endpoint</strong>, để backend thêm trước.</li></ol><h2 id="quyet-đinh-ky-thuat-đa-chot" tabindex="-1">Quyết định kỹ thuật đã chốt <a class="header-anchor" href="#quyet-đinh-ky-thuat-đa-chot" aria-label="Permalink to &quot;Quyết định kỹ thuật đã chốt&quot;">​</a></h2><ul><li><strong>Charge trước khi generate (video), không phải sau khi xong</strong> — <code>credits.charge()</code> chạy ngay khi AI service nhận job (có <code>jobId</code>), trước khi job chạy xong. UI phải nói rõ &quot;đã trừ N credit, đang xử lý&quot; ngay từ Generating state.</li><li><strong>Polling pattern chuẩn</strong>: <code>refetchInterval</code> dừng tự động khi status không còn PENDING/PROCESSING — không cần tự viết timeout logic, server có sweep job riêng (mỗi 60s, timeout mặc định 600s) tự fail+refund job treo.</li><li><strong>Refund idempotent ở server</strong> — mobile không cần tự chặn double-refund, nhưng không nên tự ý gọi lại generate khi job FAILED mà chưa kiểm tra <code>refunded</code> flag.</li><li><strong>Phân biệt rõ 3 loại lỗi trong UI copy</strong>: <code>INVALID_REQUEST</code>/<code>AI_SERVICE_UNAVAILABLE</code> (không trừ credit, fail trước khi charge) vs job fail sau khi đã charge (có refund) vs <code>INSUFFICIENT_AI_CREDIT</code> (402, riêng biệt, link sang G7).</li><li><strong>Image generation: KHÔNG hiện &quot;đã trừ credit&quot;</strong> cho tới khi backend xác nhận credit flow thật — <code>AiGenerationController</code> hiện không gọi <code>AiCreditService</code> ở tầng Java, có thể là gap hệ thống chưa vá, không phải hành vi đã xác nhận.</li><li><strong>Không giả lập % tiến trình không có thật</strong> — chỉ phản ánh đúng PENDING/PROCESSING/COMPLETED/FAILED từ server.</li></ul><h2 id="viec-can-xac-nhan-truoc-khi-code-chua-lam-xem-spec-muc-8" tabindex="-1">Việc cần xác nhận trước khi code (chưa làm, xem spec mục 8) <a class="header-anchor" href="#viec-can-xac-nhan-truoc-khi-code-chua-lam-xem-spec-muc-8" aria-label="Permalink to &quot;Việc cần xác nhận trước khi code (chưa làm, xem spec mục 8)&quot;">​</a></h2><ul><li>Push notification khi job video xong — server chưa có cơ chế push (FCM/APNs/Expo), cần task riêng ở backend trước khi mobile tận dụng; nếu không có, chỉ polling khi app foreground.</li><li>Credit flow Image generation — xác nhận với BE ai-service Python có tự trừ credit hay là gap thật trước khi hiển thị bất kỳ thông tin credit nào cho luồng Image.</li><li>Image generation không có job/status polling — nếu thời gian xử lý thật dài (gần bằng video), cần bàn đổi sang pattern async/job trước khi mobile cam kết UX đồng bộ (gọi 1 lần, chờ response).</li><li>Endpoint <code>GET /captions</code> list (lịch sử caption generation) chưa tồn tại — cần backend thêm tương tự <code>GET /videos</code> nếu muốn Credit History đầy đủ cả 2 loại.</li></ul><h2 id="rui-ro-con-mo" tabindex="-1">Rủi ro còn mở <a class="header-anchor" href="#rui-ro-con-mo" aria-label="Permalink to &quot;Rủi ro còn mở&quot;">​</a></h2><ul><li>Video Veo có thể vài chục MB — cảnh báo dùng Wifi khi preview/download, dùng signed URL stream trực tiếp (không proxy qua app) để tránh tốn băng thông app.</li><li>Shape request/response thật của <code>POST /image/commercial/generate</code> chưa có DTO Java (JsonNode tự do) — phải lấy từ <code>brandhub-ai-service</code> Python hoặc web frontend trước khi code Generate Image.</li></ul>',10)])])}const p=n(c,[["render",a]]);export{u as __pageData,p as default};
